'use strict';
// Keep the playing surface responsive; editor panels are refreshed when opened.
let selectionFrame=0,fxOverviewFrame=0;
function requestSelectionRender(){if(selectionFrame)return;selectionFrame=requestAnimationFrame(()=>{selectionFrame=0;const compact=window.matchMedia?.('(max-width:650px)').matches&&!$('.machine').classList.contains('editor-mode')&&$('#effects').hidden&&!(typeof chopSurface!=='undefined'&&chopSurface);if(!compact){render();return}const p=pads[selected];$('#padChoice').value=selected;$('#padLabel').textContent='PAD '+padName(selected);for(const [i,el]of [...$('#pads').children].entries()){el.classList.toggle('selected',bank*16+i===selected);el.setAttribute('aria-pressed',bank*16+i===selected)}$('#mute').textContent=p.muted?'RÉACTIVER CE PAD':'RENDRE MUET';$('#mute').setAttribute('aria-pressed',!!p.muted);$('#mute').classList.toggle('active',!!p.muted);for(const id of ['solo','soloSelected']){$('#'+id).setAttribute('aria-pressed',id==='solo'?!!p.solo:pads.some(x=>x.solo));$('#'+id).classList.toggle('active',id==='solo'?!!p.solo:pads.some(x=>x.solo))}$('#soloSelected').textContent=pads.some(x=>x.solo)?'QUITTER SOLO':'ISOLER CE PAD';renderSteps(true);renderFxOverview()})}
function releasePlayingTouches(){for(const [token,index]of [...pressed])releasePad(index%16,token);if(typeof releasePadPerfTouches==='function')releasePadPerfTouches()}
function effectsOverview(){const p=pads[selected],individual=PocketFX.normalized(p.padFX),classic=classicSettings(true),grain=effectSettings(),rackActive=classic.type!=='off'&&classic.wet>0||grain.wet>0&&(grain.enabled||grain.delayEnabled),rackNames=[...(classic.type!=='off'&&classic.wet>0?[PocketFX.names[classic.type]]:[]),...(grain.enabled&&grain.wet>0?['Granulateur']:[]),...(grain.delayEnabled&&grain.wet>0?['Délai stéréo']:[])],target=fxScope==='all'?'tous les pads':fxScope==='pad'?padName(fxPad):fxGroup.size+' pads du groupe',globals=[];if(typeof padPerformanceState!=='undefined')for(const e of padPerformanceState.active.slice(-4))if(padPerformanceState.settings[e.id].wet>0)globals.push(padPerfDefinitions[e.id][0]);if(typeof flexSettings!=='undefined'&&flexSettings.type&&flexSettings.wet>0)globals.push('Flex Beat');if(typeof masterCompSettings!=='undefined'&&masterCompSettings.enabled)globals.push('Compresseur');return {individual:padName(selected)+' · '+(individual.type!=='off'&&individual.wet>0?PocketFX.names[individual.type]+' '+Math.round(individual.wet*100)+' %':'sans effet individuel'),rack:'Rack → '+target+' · '+(rackActive?rackNames.join(' + '):fxBypass?'A/B original':'désactivé')+(rackActive&&fxScope!=='all'?' · '+(isFxTarget(selected)?'ce pad est traité':'ce pad est hors cible'):''),global:'Global → tous les pads · '+(globals.join(' + ')||'aucun effet de performance'),rackActive}}
function renderFxOverview(){const state=effectsOverview();$('#playingFxIndividual').textContent=state.individual;$('#playingFxRack').textContent=state.rack;$('#playingFxGlobal').textContent=state.global;for(const [i,el]of [...$('#pads').children].entries())el.classList.toggle('rack-target',state.rackActive&&isFxTarget(bank*16+i))}
function requestFxOverview(){if(!fxOverviewFrame)fxOverviewFrame=requestAnimationFrame(()=>{fxOverviewFrame=0;renderFxOverview()})}
function audioTimingInfo(c){if(!c)return 'Activez l’audio avant de jouer. Casque filaire conseillé pour limiter le retard.';const base=Number(c.baseLatency),output=Number(c.outputLatency),knownBase=Number.isFinite(base)&&base>=0,knownOutput=Number.isFinite(output)&&output>=0;return (c.sampleRate/1000).toFixed(1)+' kHz · '+(!knownBase&&!knownOutput?'délai de sortie non communiqué':knownBase&&knownOutput?'sortie estimée '+Math.round((base+output)*1000)+' ms':'délai audio partiel '+Math.round((knownBase?base:output)*1000)+' ms')+' · estimation du navigateur, hors geste tactile. Le Bluetooth peut ajouter du retard.'}
if(!window.POCKET_PARITY_TEST){window.addEventListener('blur',releasePlayingTouches);$('#playingFxOpen').onclick=()=>{showPanel('effects');$('#individualPadName').scrollIntoView({behavior:'smooth',block:'center'})};renderFxOverview()}
